INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('148', '23', '5', '5', 'calculation', '12', '计算 \(I=\oint_\Gamma(3y-x)\,dx-5z\,dz\)，其中 \(\Gamma\) 为 \(x^2+y^2+z^2=8\) 与 \(x^2+y^2=2z\) 的交线，从 \(z\) 轴正向看取逆时针方向。', '\(I=0\)。', '联立得 \(z=2,x^2+y^2=4\)。取 \(x=2\cos t,y=2\sin t,z=2\) 代入一周积分即得。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 计算 (I= (3y-x) ,dx-5z ,dz )，其中 ( ) 为 (x 2+y 2+z 2=8 ) 与 (x 2+y 2=2z ) 的交线，从 (z ) 轴正向看取逆时针方向。 (I=0 )。 联立得 (z=2,x 2+y 2=4 )。取 (x=2 t,y=2 t,z=2 ) 代入一周积分即得。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('149', '23', '6', '6', 'proof', '12', '定义 \(\displaystyle f(n)=\sum_{m=1}^n\int_0^m\cos\frac{2\pi n[x+1]}m\,dx\)。证明 \(f(n)\) 等于 \(n\) 的所有正因子之和，并计算 \(f(2021)\)。', '\(f(n)=\sigma(n)\)，且 \(f(2021)=2112\)。', '把积分按单位区间分割成单位根之和：当 \(m\mid n\) 时为 \(m\)，否则为 0。又 \(2021=43\times47\)，故 \((1+43)(1+47)=2112\)。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 定义 ( f(n)= m=1 n 0 m 2 n[x+1] m ,dx )。证明 (f(n) ) 等于 (n ) 的所有正因子之和，并计算 (f(2021) )。 (f(n)= (n) )，且 (f(2021)=2112 )。 把积分按单位区间分割成单位根之和：当 (m n ) 时为 (m )，否则为 0。又 (2021=43 47 )，故 ((1+43)(1+47)=2112 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('150', '23', '7', '7', 'comprehensive', '14', '设 \(\displaystyle u_n=\int_0^1\frac{dt}{(1+t^4)^n}\)。

1. 证明 \(u_n\) 收敛并求极限；
2. 证明 \(\sum_{n=1}^\infty(-1)^nu_n\) 条件收敛；
3. 证明 \(p\ge1\) 时 \(\sum u_n/n^p\) 收敛，并求 \(\sum u_n/n\)。', '1. \(u_n\to0\)。 2. 级数条件收敛。 3. 对所有 \(p\ge1\) 收敛，且
\[\sum_{n=1}^\infty\frac{u_n}{n}=\ln2+\frac{\sqrt2}{2}\left[\pi+2\ln(1+\sqrt2)\right].\]', '分段夹逼得 \(u_n\to0\)；由单调性用 Leibniz 判别，另以调和级数作下界证非绝对收敛。分部积分得 \(u_n/n=1/(n2^n)+4(u_n-u_{n+1})\)，求和并代入 \(u_1\) 即得。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 设 ( u n= 0 1 dt (1+t 4) n )。 1. 证明 (u n ) 收敛并求极限； 2. 证明 ( n=1 (-1) nu n ) 条件收敛； 3. 证明 (p 1 ) 时 ( u n/n p ) 收敛，并求 ( u n/n )。 1. (u n 0 )。 2. 级数条件收敛。 3. 对所有 (p 1 ) 收敛，且 [ n=1 u n n = 2+ 2 2 [ +2 (1+ 2) ]. ] 分段夹逼得 (u n 0 )；由单调性用 Leibniz 判别，另以调和级数作下界证非绝对收敛。分部积分得 (u n/n=1/(n2 n)+4(u n-u n+1 ) )，求和并代入 (u 1 ) 即得。', '5', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('151', '24', '1', '1', 'calculation', '30', '填空题，共 5 小题，每小题 6 分。

1. 求 \(\displaystyle\lim_{n\to\infty}\sum_{k=1}^n\frac{k}{n^2}\sin^2\left(1+\frac{k}{n}\right)\)。
2. \(u=xyz+e^{xyz}\)，求其在 \(P_0(1,1,-1)\) 沿 \(P_0P_1\)（\(P_1=(2,-1,0)\)）方向的方向导数。
3. \(\Gamma:x^2+y^2+z^2=a^2,x+y+z=0\)，求 \(\displaystyle\oint_\Gamma(1+x)^2ds\)。
4. 三阶矩阵 \(A\) 满足 \(|A^*|=16,|A|>0\)，且 \(ABA^{-1}=BA^{-1}+3I\)，求 \(B\)。
5. \(u=x_1+x_2/x_1+x_3/x_2+2/x_3\ (x_i>0)\)，求全部极值点。', '1. \(\displaystyle\frac{2-2\sin4-\cos4+\cos2}{8}\)。
2. \(\displaystyle\frac{2(1+e^{-1})}{\sqrt6}\)。 3. \(\displaystyle2\pi a(1+a^2/3)\)。
4. \(\displaystyle B=3(I-A^{-1})^{-1}=3(I-A^*/4)^{-1}\)。
5. 唯一极值点 \(\displaystyle(2^{1/4},2^{1/2},2^{3/4})\)，为极小值点。', '1. 化为 Riemann 积分。 2. 梯度点乘单位方向向量。 3. 利用圆周关于 \(x,y,z\) 的对称性。
4. 由 \(|A^*|=|A|^2\) 得 \(|A|=4\)，再整理矩阵方程。 5. 用 AM-GM 或驻点方程。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( n k=1 n k n 2 2 (1+ k n ) )。 2. (u=xyz+e xyz )，求其在 (P 0(1,1,-1) ) 沿 (P 0P 1 )（ (P 1=(2,-1,0) )）方向的方向导数。 3. ( :x 2+y 2+z 2=a 2,x+y+z=0 )，求 ( (1+x) 2ds )。 4. 三阶矩阵 (A ) 满足 (|A *|=16,|A|>0 )，且 (ABA -1 =BA -1 +3I )，求 (B )。 5. (u=x 1+x 2/x 1+x 3/x 2+2/x 3 (x i>0) )，求全部极值点。 1. ( 2-2 4- 4+ 2 8 )。 2. ( 2(1+e -1 ) 6 )。 3. ( 2 a(1+a 2/3) )。 4. ( B=3(I-A -1 ) -1 =3(I-A */4) -1 )。 5. 唯一极值点 ( (2 1/4 ,2 1/2 ,2 3/4 ) )，为极小值点。 1. 化为 Riemann 积分。 2. 梯度点乘单位方向向量。 3. 利用圆周关于 (x,y,z ) 的对称性。 4. 由 (|A *|=|A| 2 ) 得 (|A|=4 )，再整理矩阵方程。 5. 用 AM-GM 或驻点方程。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('152', '24', '2', '2', 'calculation', '12', '设 \(n\) 为正整数，求
\[\lim_{x\to0}\frac{\displaystyle\prod_{k=1}^n\left(\frac{1+kx}{1-kx}\right)^{1/(2k)}-1}{3\pi\arcsin x-(1+x^2)\arctan^3x}.\]', '\(\displaystyle\frac{n}{3\pi}\)。', '记乘积为 \(f(x)\)，对数求导得 \(f(0)=1,f''(0)=n\)。分母等价于 \(3\pi x\)，故极限为 \(n/(3\pi)\)。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (n ) 为正整数，求 [ x 0 k=1 n ( 1+kx 1-kx ) 1/(2k) -1 3 x-(1+x 2) 3x . ] ( n 3 )。 记乘积为 (f(x) )，对数求导得 (f(0)=1,f''(0)=n )。分母等价于 (3 x )，故极限为 (n/(3 ) )。', '1', 'published') ON CONFLICT (id) DO NOTHING;